(function () {
  var result = { sources: $.sources, advisories: $.advisories, upgrade: $.upgrade,
                 deprecation: $.deprecation, transitiveDependencies: $.transitiveDependencies };
  // A version deps.dev has no dependency graph for would otherwise look clean. A brand-new release
  // can have none yet: @strapi/strapi@5.60.0 had none a few hours after it was published.
  if (!$.sources || !$.sources.dependencyGraph) {
    result.warning = "deps.dev has no dependency data for this version: it may be too new for deps.dev to have " +
      "resolved its dependencies yet, or may not exist, or deps.dev may be failing, so this result proves nothing";
  } else if (!$.sources.osv) {
    result.warning = "OSV.dev was unavailable, so the package's own advisories are unknown";
  }
  return result;
})();
